                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                action: "send",
                verb: "GET",
                beanAmount: +beanCount.innerHTML,
                timestamp: +currTime
            })
        })
        .then(response => {
            return response.json();
        })
        .then(data => {
            if (data.error) {
                alert("Error sending beans")
            } else {
                alert("Beans sent successfully!");
            }
        });
    }

}

window.onload = function () {
    $.ajax({
        url: 'https://api.mall.here',
        type: 'GET',
        success: function (response) {
            console.log(response.data)
            if (!response.data || !response.data.items || response.data.items.length < 1) {
                //nothing to show
            } else {
                const dataParse = response.data.items[0].matches ? response.data.items[0].matches : [];

                const items = []
                dataParse.forEach((element, index) => {
                    let itemData = { id: element.id };

                    itemData.quantity = parseInt(element.quantity, 10); 
                    itemData.tagColors = {}; //set to default

                    // Add tag colors from item's parent
                    if (element.tag !== undefined) {
                        itemData.tagColors[element.tag] = element.color;
                    } 

                    // Add level
                    const levels = ['gold', 'silver', 'bronze'];
                    let currentLevel = '';
                    for (let i = 0; i < levels.length; i++) {
                        const levelTag = levels[i];
                        if (element.level === levelTag) {
                            currentLevel = levelTag;
                            break;
                        }
                    }

                    if (currentLevel === '') {
                        currentLevel = 'none';
                    }
                    itemData.level = currentLevel;

                    const updatedItem = Object.assign({}, itemData);
                    items.push(updatedItem);
                });

                chartDom("#lineChart").draw({
                    points: items,
                    series: [{
                        name: 'Bean History',
                        color: "#4CAF50"
                    }]
                });
            }
        }
    });
}
