class Produk{
    public string ID;
    public string Name;
    public int Quantity;
    public string ProductType; // 'makanan', 'minuman', 'membaca', 'sepatu', 'kain', 'pakaian'
    public string category;
    public string PricePerItem;
}

public class MakananClass : Produk {
    protected double CostRounded;

    public MakananClass(string ID, string Name, int Quantity, string ProductType, string Category, 
                        string PricePerItem) :
        base(ID, Name, Quantity, ProductType, Category, PricePerItem)
    {
        if (!int.TryParse(PricePerItem, out int price))
            throw new ArgumentException("Price harus berupa angka!");
        CostRounded = Math.Round(price, 2);
    }

    public override string ToString() => $"{Name} ({Quantity}) | {Category}: Rp {CostRounded:F2}";
}

public class KainClass : Produk {
    private double TotalCost;

    public KainClass(string ID, string Name, int Quantity, string ProductType, string Category, 
                    string PricePerItem) :
        base(ID, Name, Quantity, ProductType, Category, PricePerItem)
    {
        if (!double.TryParse(PricePerItem, out double price))
            throw new ArgumentException("Biaya per unit harus berupa angka!");

        if (price < 0)
            throw new ArgumentException("Biaya per unit tidak boleh negatif!");

        TotalCost = quantity * price;
    }

    public override string ToString() => $"{Name} ({Quantity}) | {Category}: Rp {TotalCost:F2}";
}

